--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: check_rate_limit(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_rate_limit(p_user_id uuid, p_action text, p_max_per_minute integer DEFAULT 10, p_max_per_hour integer DEFAULT 100) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  count_minute INT;
  count_hour INT;
BEGIN
  SELECT COUNT(*) INTO count_minute
  FROM rate_limits
  WHERE user_id = p_user_id
    AND action = p_action
    AND created_at > NOW() - INTERVAL '1 minute';

  IF count_minute >= p_max_per_minute THEN
    RETURN FALSE;
  END IF;

  SELECT COUNT(*) INTO count_hour
  FROM rate_limits
  WHERE user_id = p_user_id
    AND action = p_action
    AND created_at > NOW() - INTERVAL '1 hour';

  IF count_hour >= p_max_per_hour THEN
    RETURN FALSE;
  END IF;

  INSERT INTO rate_limits (user_id, action)
  VALUES (p_user_id, p_action);

  RETURN TRUE;
END;
$$;


ALTER FUNCTION public.check_rate_limit(p_user_id uuid, p_action text, p_max_per_minute integer, p_max_per_hour integer) OWNER TO postgres;

--
-- Name: check_session_anomaly(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_session_anomaly() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  recent_ips INT;
BEGIN
  SELECT COUNT(DISTINCT ip_address) INTO recent_ips
  FROM active_sessions
  WHERE user_id = NEW.user_id
    AND is_valid = TRUE
    AND last_active > NOW() - INTERVAL '5 minutes';

  IF recent_ips > 3 THEN
    UPDATE active_sessions
    SET is_valid = FALSE
    WHERE user_id = NEW.user_id
      AND id != NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_session_anomaly() OWNER TO postgres;

