--
-- Name: haversine_meters(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.haversine_meters(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT 2 * 6371000 * asin(
    sqrt(
      pow(sin(radians(lat2 - lat1) / 2), 2) +
      cos(radians(lat1)) * cos(radians(lat2)) *
      pow(sin(radians(lon2 - lon1) / 2), 2)
    )
  )
$$;


ALTER FUNCTION public.haversine_meters(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) OWNER TO postgres;

--
-- Name: FUNCTION haversine_meters(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.haversine_meters(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) IS 'Calcula distancia en metros entre dos puntos GPS usando fórmula de Haversine';


