-- Name: is_login_blocked(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_login_blocked(p_email text, p_max_attempts integer DEFAULT 5, p_lockout_minutes integer DEFAULT 15) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  failed_count INT;
BEGIN
  SELECT COUNT(*) INTO failed_count
  FROM login_attempts
  WHERE email = p_email
    AND success = FALSE
    AND attempted_at > NOW() - (p_lockout_minutes || ' minutes')::INTERVAL;

  RETURN failed_count >= p_max_attempts;
END;
$$;


