--
-- Name: community_alerts alerts_auth_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY alerts_auth_insert ON public.community_alerts FOR INSERT WITH CHECK (((auth.uid() IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
   FROM public.user_security
  WHERE ((user_security.user_id = auth.uid()) AND (user_security.is_banned = true)))))));


--
-- Name: community_alerts alerts_auth_insert_secure; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY alerts_auth_insert_secure ON public.community_alerts FOR INSERT WITH CHECK (((auth.uid() IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
   FROM public.user_security
  WHERE ((user_security.user_id = auth.uid()) AND (user_security.is_banned = true)))))));


--
-- Name: community_alerts alerts_insert_authenticated; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY alerts_insert_authenticated ON public.community_alerts FOR INSERT WITH CHECK (((auth.uid() IS NOT NULL) AND (reporter_id = auth.uid())));


--
-- Name: community_alerts alerts_read_active; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY alerts_read_active ON public.community_alerts FOR SELECT USING ((status = ANY (ARRAY['ACTIVE'::text, 'CONFIRMED'::text])));


